<script>
  let currentStep = 0;
  const titleEl = document.getElementById('step-title');
  const descEl = document.getElementById('step-desc');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');

  // Elements to toggle per step
  function updateUI(step) {
    // Reset all active elements
    document.getElementById('active1').setAttribute('opacity', '0');
    document.getElementById('particle1').setAttribute('opacity', '0');
    ['line2a','line2b','line2c'].forEach(id => {
      document.getElementById(id).style.display = 'none';
    });
    ['active2a','active2b','active2c'].forEach(id => {
      document.getElementById(id).setAttribute('opacity', '0');
    });
    ['particle2a','particle2b','particle2c'].forEach(id => {
      document.getElementById(id).setAttribute('opacity', '0');
    });

    switch(step) {
      case 1: // Step 1 - Client to Service
        document.getElementById('active1').setAttribute('opacity', '1');
        document.getElementById('particle1').setAttribute('opacity', '1');
        titleEl.textContent = 'Step 1: Request arrives at the Service';
        descEl.innerHTML = `A client sends a request to the <strong>Service ClusterIP</strong> (10.96.1.42:80). The client doesn't know about individual Pods yet — it only knows the stable Service IP, which never changes even if Pods are recreated.`;
        break;

      case 2: // Step 2 - kube-proxy intercepts
        document.getElementById('active1').setAttribute('opacity', '1');
        document.getElementById('particle1').setAttribute('opacity', '1');
        ['line2a','line2b','line2c'].forEach(id => {
          document.getElementById(id).style.display = '';
        });
        titleEl.textContent = 'Step 2: kube-proxy intercepts the traffic';
        descEl.innerHTML = `<strong>kube-proxy</strong> on each node manages iptables/IPVS rules that catch all traffic to the Service IP. It knows the list of healthy backend Pods (from the <code>Selector</code>) and prepares to load-balance among them.`;
        break;

      case 3: // Step 3 - Round robin to pods
        document.getElementById('active1').setAttribute('opacity', '1');
        document.getElementById('particle1').setAttribute('opacity', '1');
        ['line2a','line2b','line2c'].forEach(id => {
          document.getElementById(id).style.display = '';
        });
        ['active2a','active2b','active2c'].forEach(id => {
          document.getElementById(id).setAttribute('opacity', '0.7');
        });
        titleEl.textContent = 'Step 3: Load-balanced to backend Pods';
        descEl.innerHTML = `Traffic is distributed across the three healthy Pods using a <strong>round-robin</strong> strategy. Each request from the same ClientIP may go to different Pods (unless session affinity is configured). Unhealthy Pods are automatically removed from the rotation.`;
        break;

      case 4: // Step 4 - Pod receives
        ['line2a','line2b','line2c'].forEach(id => {
          document.getElementById(id).style.display = '';
        });
        ['active2a','active2b','active2c'].forEach(id => {
          document.getElementById(id).setAttribute('opacity', '0.7');
        });
        document.getElementById('particle1').setAttribute('opacity', '1');
        document.getElementById('particle2a').setAttribute('opacity', '1');
        document.getElementById('particle2b').setAttribute('opacity', '1');
        document.getElementById('particle2c').setAttribute('opacity', '1');
        titleEl.textContent = 'Step 4: Pod receives and responds';
        descEl.innerHTML = `The selected <strong>Pod</strong> (on any node in the cluster) receives the traffic on port <strong>8080</strong>, processes it, and sends a response back. The return path follows the reverse connection tracking rules so the Client never sees the Pod IPs.`;
        break;
    }

    // Update button states
    prevBtn.disabled = step === 0;
    nextBtn.disabled = step === 4;
    prevBtn.style.opacity = step === 0 ? '0.5' : '1';
    nextBtn.style.opacity = step === 4 ? '0.5' : '1';

    document.querySelector('text:last-of-type').textContent = 
      step === 0 ? 'Ready to begin — Use the buttons below to advance' :
      `Step ${step} of 4`;
  }

  function goStep(step) {
    currentStep = Math.max(0, Math.min(4, step));
    updateUI(currentStep);
  }

  // Init
  updateUI(0);
</script>
